describe("fixed private GitHub HTTP transport", () => {
  it("T-AC-44 keeps authentication private, blocks redirects and derives the fixed GitHub origin", async () => {
    let target = "",
      options: RequestInit | undefined;
    const transport = new FetchGithubAppTransport(
      async (installation, mode) => {
        expect({ installation, mode }).toEqual({
          installation: repository.installationId,
          mode: "installation",
        });
        return "synthetic-private-auth";
      },
      async (input, init) => {
        target = String(input);
        options = init;
        return Response.json({ id: repository.repositoryId });
      },
    );
    expect(
      await transport.get("/repos/fixture/observatory", repository.installationId, "installation"),
    ).toEqual({ id: repository.repositoryId });
    expect(target).toBe("https://api.github.com/repos/fixture/observatory");
    expect(options?.redirect).toBe("error");
    expect(new Headers(options?.headers).get("authorization")).toBe(
      "Bearer synthetic-private-auth",
    );
  });
  it.each([
    "https://caller.invalid/repos/a/b",
    "//caller.invalid/repos/a/b",
    "/user",
    "/repos/fixture/observatory/actions/runs",
    "/repos/fixture/observatory?host=caller.invalid",
  ])(
    "T-AC-44 rejects nonallowlisted transport path %s before requesting authorization",
    async (path) => {
      let authorized = false,
        requested = false;
      const transport = new FetchGithubAppTransport(
        async () => {
          authorized = true;
          return "synthetic";
        },
        async () => {
          requested = true;
          return Response.json({});
        },
      );
      await expect(
        transport.get(path, repository.installationId, "installation"),
      ).rejects.toMatchObject({ code: "FORBIDDEN" });
      expect({ authorized, requested }).toEqual({ authorized: false, requested: false });
    },
  );
  it.each([401, 403, 404, 429, 500])(
    "T-AC-44 treats upstream status %i as unavailable source authority",
    async (status) => {
      const transport = new FetchGithubAppTransport(
        async () => "synthetic-private-auth",
        async () => new Response("private-provider-diagnostic", { status }),
      );
      await expect(
        transport.get("/repos/fixture/observatory", repository.installationId, "installation"),
      ).rejects.toMatchObject({ code: "SOURCE_UNAVAILABLE", status: 503 });
    },
  );
  it.each(["ascii", "multibyte"])(
    "T-AC-44 bounds upstream JSON by actual bytes for %s responses",
    async (mode) => {
      const body = JSON.stringify({
        diagnostic: (mode === "ascii" ? "x" : "é").repeat(mode === "ascii" ? 1048577 : 600000),
      });
      expect(Buffer.byteLength(body)).toBeGreaterThan(1048576);
      const transport = new FetchGithubAppTransport(
        async () => "synthetic-private-auth",
        async () => new Response(body),
      );
      const result = await transport
        .get("/repos/fixture/observatory", repository.installationId, "installation")
        .then(
          () => ({ accepted: true }),
          (error: unknown) => ({ accepted: false, error }),
        );
      expect(result).toMatchObject({
        accepted: false,
        error: { code: "SOURCE_UNAVAILABLE", status: 503 },
      });
    },
  );
});
